// Gives card links (/cards/tk802/049) a rich preview when shared: the card's name,
// stats and text, with the card itself as the image.
//
// Its own function rather than part of list-preview.js so that function's cold
// starts don't pay to load every card. Preview text and images come from
// netlify/edge-functions/lib/card-preview-data.js, generated by
// scripts/gen-card-previews.mjs.

import previews, { SITE_BASE, CDN_BASE } from './lib/card-preview-data.js'
import { withPreviewTags } from './lib/og-tags.js'

export const config = { path: '/cards/*' }

// /cards/:set/:number → its preview, or null for anything else. Copy link always
// produces the canonical spelling, so a hand-typed /cards/TK802/49 opens the card
// but gets the generic preview, which isn't worth normalising for here.
function lookup(pathname) {
  const parts = pathname.replace(/^\/+|\/+$/g, '').split('/').map(decodeURIComponent)
  if (parts.length !== 3) return null
  const preview = previews[`${parts[1]}-${parts[2]}`]
  if (!preview) return null
  const [name, description, asset] = preview
  return {
    title: `${name} · BuildUVS`,
    description,
    image: `${CDN_BASE}/${asset}`,
    // The card is the point of the link, so show it large.
    twitterCard: 'summary_large_image',
  }
}

export default async (request, context) => {
  const res = await context.next()
  const url = new URL(request.url)
  return withPreviewTags(res, lookup(url.pathname), SITE_BASE + url.pathname)
}
